const D = () => window.LYASocialesDibujos;
/* elegir: o = [buena, malas…], p = [porqué de cada mala, en el mismo orden] */
const E = (d, g, e, o, p, pi, r, x = {}) => ({d, g, e, o, p: ["", ...p], pi, r: [].concat(r), ...x});
